from pathlib import Path
import json, platform
import joblib, pandas as pd, sklearn
from sklearn.model_selection import train_test_split
from sklearn.metrics import accuracy_score, precision_score, recall_score, f1_score, confusion_matrix, classification_report, roc_auc_score, balanced_accuracy_score
from sklearn.tree import export_text
from backend.app import app
root=Path(__file__).resolve().parents[1]
b=joblib.load(root/'models/loan_decision_tree_model.joblib'); m=b['model']
df=pd.read_csv(root/'data/loan_prediction_dataset.csv'); e=df.copy()
e['Total_Income']=e.ApplicantIncome+e.CoapplicantIncome
e['Income_to_Loan_Ratio']=e.Total_Income/(e.LoanAmount+1e-5)
e['EMI_Estimate']=e.LoanAmount*1000/(e.Loan_Amount_Term+1e-5)
for c,mp in b['cat_mappings'].items(): e[c]=e[c].map(mp).fillna(0).astype(int)
tr,te=train_test_split(e,test_size=.2,random_state=42,stratify=e.Loan_Status)
def metrics(y,p,prob=None):
 d={'n':len(y),'class_counts':{str(k):int(v) for k,v in y.value_counts().items()},'accuracy':accuracy_score(y,p),'precision':precision_score(y,p),'recall':recall_score(y,p),'f1':f1_score(y,p),'balanced_accuracy':balanced_accuracy_score(y,p),'confusion_matrix':confusion_matrix(y,p).tolist(),'classification_report':classification_report(y,p,output_dict=True)}
 if prob is not None:d['roc_auc']=roc_auc_score(y,prob)
 return d
r={'date':'2026-10-30','python':platform.python_version(),'sklearn':sklearn.__version__,'missing_values':int(df.isna().sum().sum()),'duplicate_rows':int(df.duplicated().sum()),'parameters':m.get_params(),'depth':int(m.get_depth()),'leaves':int(m.get_n_leaves()),'features':b['feature_cols'],'mappings':b['cat_mappings'],'feature_importances':dict(zip(b['feature_cols'],m.feature_importances_.tolist()))}
for name,part in [('training',tr),('testing',te)]:r[name]=metrics(part.Loan_Status,m.predict(part[b['feature_cols']]),m.predict_proba(part[b['feature_cols']])[:,1])
c=app.test_client(); samples=c.get('/api/samples').get_json()['samples'];r['samples']=[{'id':s['id'],'input':s['data'],'result':c.post('/api/predict',json=s['data']).get_json()} for s in samples]
r['examples']={}
p=m.predict(te[b['feature_cols']])
for label,actual,pred in [('TP',1,1),('FP',0,1),('TN',0,0),('FN',1,0)]:
 idx=te.index[(te.Loan_Status==actual)&(p==pred)][0];r['examples'][label]={'record':df.loc[idx].to_dict(),'prediction':pred}
r['training_examples']=df.loc[tr.index[:3]].to_dict(orient='records')
r['tree_rules']=export_text(m,feature_names=b['feature_cols'])
(root/'docs/evaluation_evidence.json').write_text(json.dumps(r,indent=2),encoding='utf-8')
print(json.dumps({k:r[k] for k in ['training','testing','missing_values','duplicate_rows','depth','leaves']},indent=2))


# Build a readable report from the verified evidence.
lines=['# CrediPredict AI: Detailed Project, Training and Testing Report', '', 'Verified on 30 October 2026 using the existing dataset and saved model. No retraining was performed.', '', '## 1. Project overview', '', 'CrediPredict is an academic loan approval classification web application. A Flask backend loads a scikit-learn Decision Tree, receives applicant details, constructs features, and returns an approval/rejection decision with probabilities and the tree decision path. The browser interface displays the result and model metrics.', '', 'The target is Loan_Status: Y = 1 (approved, the positive class), N = 0 (rejected, the negative class). These are synthetic approval labels, not observed repayment or default outcomes. Accuracy on these records does not establish real-world credit performance.', '', '## 2. Architecture and files', '', '| Component | File / responsibility |','|---|---|','| Launcher | app.py and start_app.bat |','| Backend | backend/app.py: validation, inference, affordability rule, API responses |','| Frontend | frontend/templates/dashboard.html and frontend/static: user interface |','| Training | ml/train_model.py: dataset generation, feature engineering, split, fitting, evaluation |','| Dataset | data/loan_prediction_dataset.csv |','| Runtime model | models/loan_decision_tree_model.joblib |','| Exports | classifier-only pickle, preprocessing metadata pickle, combined bundle pickle |','| Saved metrics | models/model_metrics.json |','| Automated tests | tests/test_model.py |', '', 'Flow: applicant form -> POST /api/predict -> input validation -> feature engineering and encoding -> tree prediction -> affordability override if required -> JSON response -> result display.', '', '## 3. Dataset and training/testing cases', '', 'The project generates 10,000 synthetic records with NumPy seed 42. Although source comments call it Kaggle-aligned, it is locally generated data, not a downloaded or independently verified Kaggle dataset. Labels are generated probabilistically, with credit history the main influence and additional effects from property area, education and affordability.', '', '| Partition | Total cases | Approved (1) | Rejected (0) | Purpose |','|---|---:|---:|---:|---|']
for label,key,purpose in [('Training','training','Fit the decision tree'),('Testing','testing','Evaluate the fitted tree on held-out rows')]:
 q=r[key];lines.append(f"| {label} | {q['n']} | {q['class_counts']['1']} | {q['class_counts']['0']} | {purpose} |")
lines += ['', 'Overall: 7,276 approved and 2,724 rejected records. Split: 80% training / 20% testing, random_state=42, stratified by target. There is no separate validation set or cross-validation in the training code. The reconstructed split assumes the current CSV matches the original training dataset; the reproduced saved holdout matrix supports consistency.', '', f"Data checks: {r['missing_values']} missing cells and {r['duplicate_rows']} fully duplicated rows. Loan_ID is excluded from model features. Unique IDs mean the full-row duplicate check alone does not establish absence of repeated feature profiles.", '', 'A training case is a labeled row used for fitting. A testing case is a held-out labeled row used for evaluation. An API test case is a software behavior check; these three meanings should not be confused.', '', '## 4. Inputs and preprocessing', '', '| Input | Meaning / allowed categories |','|---|---|','| ApplicantIncome | Applicant monthly income |','| CoapplicantIncome | Coapplicant monthly income, may be zero |','| LoanAmount | Loan principal in thousands; 150 means 150,000 |','| Loan_Amount_Term | Term in months |','| Credit_History | 0 or 1 |','| Gender | Male / Female |','| Married | Yes / No |','| Dependents | 0 / 1 / 2 / 3+ |','| Education | Graduate / Not Graduate |','| Self_Employed | Yes / No |','| Property_Area | Rural / Semiurban / Urban |', '', 'Three engineered features produce 14 total model inputs:', '', '- Total_Income = ApplicantIncome + CoapplicantIncome.', '- Income_to_Loan_Ratio = Total_Income / (LoanAmount + 0.00001). This uses loan thousands, so it is not a dimensionless debt ratio.', '- EMI_Estimate = LoanAmount × 1000 / (Loan_Amount_Term + 0.00001). This is principal divided by term; interest is not included.', '', 'Categorical encoding:', '', '```json',json.dumps(b['cat_mappings'],indent=2),'```', '', 'There is no scaling step. Training mapping uses fillna(0), while the API rejects explicitly supplied unknown category values. Missing API fields may receive defaults, so the API does not require every feature to be supplied.', '', '## 5. Training algorithm and configuration', '', 'The Decision Tree recursively chooses feature thresholds that reduce Gini impurity: Gini = 1 - sum(p_k squared). A terminal leaf predicts its majority class. predict_proba reports training class proportions in the leaf; these values are not independently calibrated probabilities.', '', '| Parameter | Value |','|---|---|','| criterion | gini |','| max_depth | 4 |','| min_samples_split | 20 |','| min_samples_leaf | 10 |','| random_state | 42 |','| class_weight | None |',f"| Actual depth / leaves | {r['depth']} / {r['leaves']} |", '', 'Procedure: generate records -> construct derived features -> encode categories -> select 14 features -> stratified split -> fit on 8,000 rows -> predict 2,000 held-out rows -> calculate metrics -> save model and metadata. No hyperparameter search is present.', '', '## 6. Training versus testing performance', '', 'All precision, recall and F1 values in this table treat approval (1) as positive. Percentages below are recomputed from predictions, rather than converted from rounded saved metrics.', '', '| Metric | Training | Testing |','|---|---:|---:|']
for key,label in [('accuracy','Accuracy'),('precision','Precision'),('recall','Recall / sensitivity'),('f1','F1 score'),('balanced_accuracy','Balanced accuracy'),('roc_auc','ROC AUC')]:lines.append(f"| {label} | {r['training'][key]*100:.4f}% | {r['testing'][key]*100:.4f}% |")
lines += ['', 'ROC AUC uses raw model approval probabilities; it can also be expressed as 0.852044 on the test set. The training/test accuracy gap is 0.9875 percentage points. A small gap on one synthetic split does not establish generalization to real applicants.', '', '## 7. Confusion matrices: TP, FP, TN and FN', '', 'Rows are actual labels; columns are predicted labels. scikit-learn ordering is [[TN, FP], [FN, TP]].', '', '| Partition / actual label | Predicted rejected (0) | Predicted approved (1) |','|---|---:|---:|','| Training: rejected | TN = 1308 | FP = 871 |','| Training: approved | FN = 38 | TP = 5783 |','| Testing: rejected | TN = 309 | FP = 236 |','| Testing: approved | FN = 11 | TP = 1444 |', '', '- TP = 1,444: approved label, predicted approved.', '- FP = 236: rejected label, predicted approved.', '- TN = 309: rejected label, predicted rejected.', '- FN = 11: approved label, predicted rejected.', '', 'Total correct = 1,753; total incorrect = 247; total test cases = 2,000. Predicted approved = 1,680; predicted rejected = 320.', '', '## 8. Metric formulas and interpretation', '', '| Metric | Calculation on testing cases | Result |','|---|---|---:|','| Accuracy | (TP + TN) / total = 1753 / 2000 | 87.65% |','| Precision | TP / (TP + FP) = 1444 / 1680 | 85.95% |','| Recall | TP / (TP + FN) = 1444 / 1455 | 99.24% |','| F1 | 2TP / (2TP + FP + FN) = 2888 / 3135 | 92.12% |','| Specificity | TN / (TN + FP) = 309 / 545 | 56.70% |','| False-positive rate | FP / (FP + TN) = 236 / 545 | 43.30% |','| False-negative rate | FN / (FN + TP) = 11 / 1455 | 0.76% |','| Negative predictive value | TN / (TN + FN) = 309 / 320 | 96.56% |','| Error rate | (FP + FN) / total = 247 / 2000 | 12.35% |', '', 'Precision answers: of all predicted approvals, how many have approved labels? Recall answers: of all approved labels, how many were found? F1 combines precision and recall using their harmonic mean. High approval recall coexists with low rejection recall: the model misses 236 of the 545 rejected labels. FP does not mean an observed default; no repayment outcome was measured.', '', 'An always-approve baseline gets 72.75% test accuracy. The tree improves accuracy by 14.90 percentage points. Balanced accuracy weights both class recalls equally and is 77.97%, exposing the weaker rejection performance.', '', '## 9. Per-class classification report', '', '| Class / averaging | Precision | Recall | F1 | Support |','|---|---:|---:|---:|---:|']
for key,label in [('0','Rejected'),('1','Approved'),('macro avg','Macro average'),('weighted avg','Weighted average')]:
 q=r['testing']['classification_report'][key];lines.append(f"| {label} | {q['precision']*100:.2f}% | {q['recall']*100:.2f}% | {q['f1-score']*100:.2f}% | {int(q['support'])} |")
lines += ['', 'Macro averaging gives both classes equal weight. Weighted averaging weights by support. The headline F1 of 92.12% is approval-class F1, not macro F1.', '', '## 10. Actual held-out examples', '', 'These examples are selected from the reconstructed test partition, one per outcome category. All values are actual CSV values; they are not invented demonstration records.', '', '| Outcome | Loan ID | Applicant income | Coapplicant income | Loan thousands | Term | Credit history | Actual | Predicted |','|---|---|---:|---:|---:|---:|---:|---|---|']
for label,ex in r['examples'].items():
 v=ex['record'];lines.append(f"| {label} | {v['Loan_ID']} | {v['ApplicantIncome']} | {v['CoapplicantIncome']} | {v['LoanAmount']} | {v['Loan_Amount_Term']} | {v['Credit_History']} | {v['Loan_Status']} | {'Y' if ex['prediction'] else 'N'} |")
lines += ['', '## 11. Actual training-case examples', '', '| Loan ID | Applicant income | Coapplicant income | Loan thousands | Term | Credit history | Training label |','|---|---:|---:|---:|---:|---:|---|']
for v in r['training_examples']:lines.append(f"| {v['Loan_ID']} | {v['ApplicantIncome']} | {v['CoapplicantIncome']} | {v['LoanAmount']} | {v['Loan_Amount_Term']} | {v['Credit_History']} | {v['Loan_Status']} |")
lines += ['', 'These rows contribute to fitting; performance on them is not independent validation.', '', '## 12. Demonstration scenarios', '', '| Sample | Actual API decision | Displayed approval probability |','|---|---|---:|']
for s in r['samples']:lines.append(f"| {s['id']} | {s['result']['status']} | {s['result']['approval_probability']:.2f}% |")
lines += ['', 'These three samples have no independently verified target labels; their predictions are demonstrations, not extra accuracy evidence. Full inputs and responses are recorded in evaluation_evidence.json.', '', '## 13. Automated software test cases and observed results', '', 'Executed: python -m unittest discover -s tests -v. Result: 2 test methods passed, containing the checks below. Test methods are not the same as individual assertions or data cases.', '', '| Check | Coverage | Observed result |','|---|---|---|','| Saved-model evaluation | All 2,000 holdout rows; accuracy equals saved metric and matrix equals [309,236,11,1444] | Passed |','| Model/API consistency | First 100 test records; HTTP 200, class matches tree, probabilities sum to 100, leaf ID and path length match | Passed |','| Homepage | GET / returns 200 | Passed |','| Built-in samples | Three POST requests succeed | Passed |','| Negative income | ApplicantIncome = -1 | HTTP 400, passed |','| Zero loan | LoanAmount = 0 | HTTP 400, passed |','| Zero term | Loan_Amount_Term = 0 | HTTP 400, passed |','| Invalid credit | Credit_History = 2 | HTTP 400, passed |','| Unknown category | Education = invalid | HTTP 400, passed |','| Nonfinite number | ApplicantIncome = NaN string | HTTP 400, passed |','| Null number | LoanAmount = null | HTTP 400, passed |','| Wrong JSON shape | JSON array | HTTP 400, passed |', '', 'Not verified by this suite: browser interactions, concurrency/load, all missing-field defaults, every category boundary, and complete API performance across all 2,000 holdout rows. Sample tests assert successful responses, not fixed expected decisions.', '', '## 14. Model results versus application decisions', '', 'The backend adds a rule after model prediction: rounded estimated monthly principal/income above 40% forces rejection and changes displayed probabilities to 0% approval / 100% rejection. The reported model metrics evaluate the tree alone. They must not be described as independently measured metrics of the entire guarded API.', '', 'The response decision path and leaf ID still describe the underlying tree even when the guard overrides its class. A forced 100% rejection display is a rule output, not statistical certainty. The first 100 API checks passed, but that does not evaluate every guarded case.', '', 'Suggested additional tests (proposed, not executed): principal/income just below, equal to and above 40%; negative coapplicant income; zero combined income; infinity; malformed JSON; omitted categories; every permitted category; very large out-of-distribution inputs; complete guarded-API confusion matrix; end-to-end browser submission and error display.', '', '## 15. Feature importance', '', 'Impurity-based tree importance measures how much each feature reduces impurity across splits. It is not a causal effect or fairness assessment.', '', '| Feature | Importance |','|---|---:|']
for key,val in sorted(r['feature_importances'].items(),key=lambda kv:kv[1],reverse=True):lines.append(f'| {key} | {val*100:.4f}% |')
lines += ['', 'Credit history dominance follows the synthetic label generator. Some features may have zero or tiny importance even though they are supplied as inputs.', '', '## 16. Full fitted tree rules', '', '```text',r['tree_rules'],'```', '', '## 17. Limitations and future work', '', '- Synthetic labels and one random holdout cannot establish real lending performance or default prediction.', '- Class imbalance makes accuracy and approval-class F1 incomplete summaries; report specificity, balanced accuracy and both class metrics.', '- No cross-validation, independent external test data, calibrated probability study, subgroup evaluation or production monitoring is implemented.', '- Income and loan units must be consistent. The EMI estimate excludes interest and existing debts.', '- Sensitive/profile features are present; no fairness claim is supported by the current evaluation.', '- Category integer encoding introduces order to categories such as Property_Area. Compare suitable encodings during future model development.', '- Future work: use documented real labeled data, reserve an untouched test set, tune on training/validation only, compare baselines, evaluate the API guard separately, and test probability calibration and error costs.', '', '## 18. Reproduction and evidence', '', 'From the project root:', '', '```powershell','python -m unittest discover -s tests -v','python -m ml.generate_detailed_report','python app.py','```', '', 'Optional training command: python -m ml.train_model. It regenerates data and replaces saved models; it is not needed to read or reproduce this report from current artifacts.', '', f"Evaluation environment: Python {r['python']}; scikit-learn {r['sklearn']}. Dependencies declared in requirements.txt: Flask, scikit-learn, pandas, NumPy and joblib.", '', 'Evidence: docs/evaluation_evidence.json contains full-precision metrics, feature mappings, model parameters, example records, sample responses and tree rules. Source references: ml/train_model.py, backend/app.py, tests/test_model.py, data/loan_prediction_dataset.csv and models/model_metrics.json.', '', '## 19. Viva-ready explanation', '', '“Our project predicts synthetic loan approval labels using an interpretable Decision Tree. We use 10,000 records split into 8,000 training and 2,000 testing cases. On the test set, TP is 1,444, TN is 309, FP is 236 and FN is 11. Accuracy is 87.65%, precision is 85.95%, recall is 99.24% and F1 is 92.12%. Recall is strong for approvals, but rejection recall is only 56.70%, so the model has an important weakness despite its high F1. The web application also applies a separate affordability rule, and these results are academic synthetic-data results.”', '']
(root/'docs/Detailed_Project_Evaluation_Report.md').write_text('\n'.join(lines),encoding='utf-8')
print('Detailed report written.')

